import React, { useState } from 'react';
import { ChevronDown, ChevronUp } from 'lucide-react';

const footerSections = [
  {
    title: 'Categories',
    links: ['Illustration', 'Craft', 'Marketing & Business', 'Photography & Video', 'Design', '3D & Animation', 'Architecture & Spaces', 'Writing', 'Fashion', 'Web & App Design', 'Calligraphy & Typography', 'Music & Audio', 'Culinary', 'Artificial Intelligence', 'Wellness']
  },
  {
    title: 'Areas',
    links: ['Traditional Illustration', 'Digital Illustration', 'Drawing', 'Arts & Crafts', 'Graphic Design', 'DIY', 'Fine Arts', 'Textile Design', 'Photography', 'Marketing', 'Painting', 'Branding & Identity', 'Character Design', '3D', 'Storytelling', 'Narrative', 'Communication']
  },
  {
    title: 'Software',
    links: ['Adobe Photoshop', 'Adobe Illustrator', 'Procreate', 'Adobe After Effects', 'Adobe Lightroom', 'Cinema 4D', 'Adobe InDesign', 'ChatGPT', 'Adobe Premiere']
  },
  {
    title: 'Lists',
    links: ['New courses', 'Top rated', 'Popular courses', 'Courses on sale']
  },
  {
    title: 'Sections',
    links: ['Courses', 'Projects', 'Creatives', 'Schools', 'Podcasts', 'Blog']
  }
];

export function Footer() {
  const [openSection, setOpenSection] = useState<string | null>(null);

  const toggleSection = (title: string) => {
    setOpenSection(openSection === title ? null : title);
  };

  return (
    <footer className="bg-[#171717] text-white pt-16 pb-8">
      <div className="max-w-7xl mx-auto px-4 md:px-8">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-8 mb-12">
          {footerSections.map((section) => (
            <div key={section.title} className="border-b border-white/10 md:border-none pb-4 md:pb-0">
              <button 
                onClick={() => toggleSection(section.title)}
                className="flex justify-between items-center w-full md:cursor-default"
              >
                <h3 className="font-bold text-lg mb-0 md:mb-4">{section.title}</h3>
                <div className="md:hidden">
                  {openSection === section.title ? <ChevronUp className="h-5 w-5" /> : <ChevronDown className="h-5 w-5" />}
                </div>
              </button>

              <ul className={`mt-4 space-y-2 text-sm text-gray-400 md:block ${openSection === section.title ? 'block' : 'hidden'}`}>
                {section.links.map(link => (
                  <li key={link}>
                    <a href="#" className="hover:text-white transition-colors">{link}</a>
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </div>

        <div className="border-t border-white/20 pt-8 flex flex-col md:flex-row justify-between items-center gap-4 text-xs text-gray-400">
          <div className="flex flex-wrap justify-center md:justify-start gap-4 md:gap-6">
            <span className="font-bold text-white tracking-widest uppercase">CreativeHub</span>
            <a href="#" className="hover:text-white">Terms of use</a>
            <a href="#" className="hover:text-white">Privacy Policy</a>
            <a href="#" className="hover:text-white">Cookies Policy</a>
            <a href="#" className="hover:text-white">Accessibility Statement</a>
          </div>
          <div className="flex gap-4">
            <button className="border border-white/30 rounded px-3 py-1 hover:bg-white/10 transition-colors">English</button>
            <button className="border border-white/30 rounded px-3 py-1 hover:bg-white/10 transition-colors">Apps</button>
          </div>
        </div>
      </div>
    </footer>
  );
}
